T = "w8-minimal-rsi"

def n(i, kind, title, body, source, confidence, tags):
    return {"id": f"{T}-{i:03d}", "kind": kind, "title": title, "body": body,
            "source": source, "confidence": confidence, "topic": T, "tags": tags}

def e(a, rel, b, note):
    return {"from": f"{T}-{a:03d}", "rel": rel, "to": f"{T}-{b:03d}", "note": note}

